import type { CardCheck } from '@/lib/flashcard-check-core'

/**
 * Card-check questions for the cards of `mcat-anatomy-physiology-mcat`: one per card, keyed by the
 * card's exact front text. Each asks the student to use the card's idea in a
 * new situation. Gate: scripts/flashcard-checks/validate.ts.
 */
const r = String.raw

export const checks: Record<string, CardCheck> = {
  [r`Compare the three muscle types.`]: {
    question: r`A biopsy shows long, unbranched, striated fibers, each containing many nuclei pushed to its edge. From which structure was the sample most likely taken?`,
    options: [r`The aortic wall, which sets vessel tone`, r`The stomach wall, which churns food`, r`The diaphragm, which drives each breath`, r`The left ventricle, which pumps blood`],
    correctAnswer: 2,
    explanation: r`Striations plus many nuclei per fiber identify skeletal muscle, and the diaphragm is skeletal muscle even though breathing usually runs without thought. The left ventricle is cardiac muscle, which is striated but branched with one or two nuclei and intercalated discs. The stomach and aortic walls are smooth muscle, which has no striations.`,
  },
  [r`What is homeostasis and its usual control mechanism?`]: {
    question: r`After a salty meal, plasma osmolarity rises and ADH release increases. The kidneys retain water, osmolarity returns to normal, and ADH release then drops back. How is this loop best classified?`,
    options: [r`Positive feedback, because ADH release rises after the first stimulus`, r`Negative feedback, because the response reverses the original change`, r`Positive feedback, because the response amplifies the original change`, r`Negative feedback, because ADH lowers the amount of water in the body`],
    correctAnswer: 1,
    explanation: r`The response (water retention) pushes osmolarity back toward its set point and so removes its own stimulus, which is the definition of negative feedback and of homeostasis. Calling it positive feedback confuses "a hormone went up" with "the change was amplified". ADH raises body water, so the option saying it lowers body water has the mechanism backwards.`,
  },
  [r`What does the liver do metabolically?`]: {
    question: r`A patient with end-stage liver failure has blood drawn after an overnight fast. Which set of results is most likely?`,
    options: [r`Low ammonia, high albumin, and low blood glucose`, r`High ammonia, low albumin, and low blood glucose`, r`High ammonia, high albumin, and high blood glucose`, r`Low ammonia, low albumin, and high blood glucose`],
    correctAnswer: 1,
    explanation: r`A failing liver cannot run the urea cycle, so ammonia builds up. It cannot make plasma proteins, so albumin falls, and it cannot release glucose from glycogen or gluconeogenesis, so fasting glucose falls. Each wrong set reverses at least one of these three liver jobs.`,
  },
  [r`What are the layers of the skin?`]: {
    question: r`A paper cut on a finger stings and oozes a little blood, but no fat is visible in the wound. What is the deepest layer the cut must have reached?`,
    options: [r`Epidermis, which carries vessels and nerve endings`, r`Dermis, which carries vessels and nerve endings`, r`Hypodermis, which is the layer of insulating fat`, r`Epidermis, which is stratified squamous tissue`],
    correctAnswer: 1,
    explanation: r`Bleeding requires a cut into tissue with blood vessels, and the most superficial layer that has them is the dermis. The epidermis is stratified squamous but avascular, so a cut confined to it cannot bleed, and it does not carry vessels. Reaching the hypodermis would expose fat, which was not seen.`,
  },
  [r`What are exocrine vs. endocrine glands?`]: {
    question: r`A stone blocks the main pancreatic duct, while the blood supply to the islets of Langerhans stays intact. Which pancreatic function is lost first?`,
    options: [r`Delivery of glucagon to the hepatic portal vein`, r`Delivery of somatostatin to the bloodstream`, r`Delivery of insulin to the bloodstream`, r`Delivery of digestive enzymes to the duodenum`],
    correctAnswer: 3,
    explanation: r`Exocrine products leave through ducts, so a blocked duct stops pancreatic enzymes from reaching the duodenum. Insulin, glucagon and somatostatin are endocrine secretions released straight into blood, so they do not depend on the duct.`,
  },
  [r`How does the lymphatic system support circulation?`]: {
    question: r`After surgeons remove the lymph nodes and vessels of the armpit, a patient's arm on that side slowly swells. What best explains the swelling?`,
    options: [r`Arterial pressure in the arm rises, so capillaries filter far more fluid`, r`Fluid filtered out of capillaries is no longer drained back to the blood`, r`Plasma albumin falls, so capillaries draw far less fluid back inward`, r`Veins of the arm are removed, so blood pools and leaks into the tissue`],
    correctAnswer: 1,
    explanation: r`Capillaries always filter slightly more fluid than they reabsorb, and lymphatic vessels return the excess to the blood. Removing them leaves that fluid in the interstitium. The surgery does not raise arterial pressure, lower plasma albumin, or remove the arm's veins.`,
  },
  [r`What are the four primary tissue types?`]: {
    question: r`A pathologist receives four samples in this order: the lining of the small intestine, a tendon, the wall of the left ventricle, and the spinal cord. Which list classifies them correctly, in the same order?`,
    options: [r`Connective, epithelial, muscle, nervous`, r`Epithelial, connective, muscle, nervous`, r`Epithelial, muscle, connective, nervous`, r`Connective, muscle, epithelial, nervous`],
    correctAnswer: 1,
    explanation: r`Linings and coverings are epithelial, tendons are supporting connective tissue, the ventricular wall contracts so it is muscle, and the spinal cord signals so it is nervous. The other lists swap the covering tissue and the supporting tissue, or mistake a tendon for muscle because it attaches to one.`,
  },
  [r`Give an example of positive feedback in physiology.`]: {
    question: r`In labor, cervical stretch triggers oxytocin release, oxytocin strengthens contractions, and stronger contractions stretch the cervix more. What finally stops this loop?`,
    options: [r`Uterine fatigue, which lowers the oxytocin set point`, r`Delivery of the baby, which removes the cervical stretch`, r`Strong contractions, which inhibit the hypothalamus`, r`High oxytocin, which shuts off the posterior pituitary`],
    correctAnswer: 1,
    explanation: r`Positive feedback amplifies its own stimulus and runs until a discrete endpoint removes that stimulus, here the birth of the baby ending the stretch on the cervix. The other choices describe a product inhibiting its own release or a set point, which is how negative feedback works, not this loop.`,
  },
  [r`A reflex arc can bypass the brain because:`]: {
    question: r`A man's spinal cord is completely cut at the neck. Tapping his patellar tendon still makes his leg kick, although he feels nothing. Why does the reflex survive?`,
    options: [r`The sensory signal reaches the motor cortex through an intact cranial nerve`, r`The stretched quadriceps contracts by itself with no neural input at all`, r`The sensory neuron synapses on the motor neuron inside a peripheral ganglion`, r`The sensory neuron synapses on the motor neuron inside the lumbar cord`],
    correctAnswer: 3,
    explanation: r`The knee-jerk is a monosynaptic reflex integrated in the spinal cord, below the injury, so it needs no signal from the brain. The synapse is in the cord's gray matter, not in a peripheral ganglion, the cortex is cut off from the leg, and the contraction still depends on the motor neuron firing.`,
  },
  [r`Gas exchange occurs across the:`]: {
    question: r`In emphysema, the walls between alveoli break down so that many small air sacs merge into a few large ones. Lung volume is unchanged. What happens to gas exchange?`,
    options: [r`It is unchanged, because the total volume of air is the same`, r`It rises, because each large sac holds more air on every breath`, r`It falls, because the total surface area for diffusion is smaller`, r`It falls, because the walls are now many cell layers thick`],
    correctAnswer: 2,
    explanation: r`Alveoli exchange gas well because together they offer a huge surface with walls one cell thick. Merging sacs keeps the volume but removes surface, so diffusion drops. The walls that remain are not thickened, and the volume of air held does not set the rate of diffusion.`,
  },
  [r`ATP is required in muscle to:`]: {
    question: r`A muscle fiber with its membrane removed sits rigid in a bath that contains Ca²⁺ but no ATP. When ATP is added to the bath, what is the first thing that happens?`,
    options: [r`Myosin heads let go of actin`, r`Ca²⁺ ions bind troponin C`, r`Myosin heads bind onto actin`, r`Tropomyosin uncovers actin`],
    correctAnswer: 0,
    explanation: r`Without ATP every myosin head stays locked on actin, which is why the fiber is rigid. ATP binding to myosin is what releases the head. Calcium was already present, so troponin had bound it and tropomyosin had already moved, and the heads were already attached.`,
  },
  [r`Natural killer cells target:`]: {
    question: r`A virus forces the cell it infects to stop displaying MHC class I on its surface. What does this change do to the cell's fate?`,
    options: [r`It hides from cytotoxic T cells but is attacked by natural killer cells`, r`It hides from helper T cells but is attacked by plasma B cells`, r`It hides from both natural killer cells and cytotoxic T cells`, r`It hides from natural killer cells but is attacked by cytotoxic T cells`],
    correctAnswer: 0,
    explanation: r`Cytotoxic T cells need viral peptide shown on MHC I, so a cell without MHC I escapes them. Natural killer cells kill exactly those cells that show too little MHC I ("missing self"). The reversed option swaps the two cell types, and helper T cells and B cells do not read MHC I.`,
  },
  [r`Menopause is characterized by:`]: {
    question: r`Two women have stopped menstruating and both have low estrogen. In woman 1 the ovaries have run out of follicles (menopause). In woman 2 the anterior pituitary has been destroyed. How do their FSH levels compare with normal?`,
    options: [r`Low in woman 1 and high in woman 2`, r`Low in woman 1 and low in woman 2`, r`High in woman 1 and high in woman 2`, r`High in woman 1 and low in woman 2`],
    correctAnswer: 3,
    explanation: r`In menopause the ovaries fail first, so the loss of estrogen and inhibin feedback lets the pituitary pour out FSH and LH. A destroyed pituitary cannot make FSH at all, so it is low. Assuming FSH is low in menopause treats the pituitary, not the ovary, as the part that failed.`,
  },
  [r`Atherosclerosis increases cardiac workload by:`]: {
    question: r`A plaque narrows a segment of coronary artery to half of its original radius. With length and blood viscosity unchanged, the resistance of that segment becomes how many times its original value?`,
    options: [r`8 times, since resistance varies as 1/r³`, r`2 times, since resistance varies as 1/r`, r`16 times, since resistance varies as 1/r⁴`, r`4 times, since resistance varies as 1/r²`],
    correctAnswer: 2,
    explanation: r`By Poiseuille's law resistance is proportional to 1/r⁴, so halving the radius multiplies resistance by 2⁴ = 16, and the heart must generate more pressure to keep the same flow. The other answers use the first, second or third power of the radius. The square would be right for cross-sectional area, not for resistance.`,
  },
  [r`The primitive streak marks:`]: {
    question: r`In an experimental embryo, epiblast cells are unable to migrate inward through the primitive streak. Which structures fail to form as the direct result?`,
    options: [r`Mesoderm and endoderm, because gastrulation is blocked`, r`Trophoblast and inner cell mass, because blastulation is blocked`, r`Zygote and polar bodies, because fertilization is blocked`, r`Morula and blastocoel, because cleavage is blocked`],
    correctAnswer: 0,
    explanation: r`The primitive streak marks the start of gastrulation: cells move in through it to become mesoderm and endoderm. Cleavage, formation of the blastocyst and fertilization all happen before the streak appears, so they are not affected by a block at this stage.`,
  },
  [r`The spleen's {{c1::red pulp}} filters aged RBCs, while its white pulp is lymphoid tissue surveilling the blood.`]: {
    question: r`Months after his spleen is removed, a patient's blood smear shows unusually many old, misshapen red cells still in circulation. Which lost function explains this?`,
    options: [r`Red pulp megakaryocytes breaking down old red cells`, r`Red pulp macrophages removing stiff, aged red cells`, r`White pulp macrophages removing stiff, aged red cells`, r`White pulp lymphocytes making antibody to red cells`],
    correctAnswer: 1,
    explanation: r`The red pulp is the spleen's blood filter: its macrophages destroy red cells too stiff to squeeze through the sinusoids. The white pulp is lymphoid tissue that watches the blood for antigen and does not cull red cells. Megakaryocytes live in marrow and make platelets.`,
  },
  [r`What is a reticulocyte, and what does its count tell you about an anemia?`]: {
    question: r`Two patients are equally anemic. Patient 1 has a reticulocyte count far above normal, and patient 2 has a count far below normal. Which pair of causes fits best?`,
    options: [r`Patient 1 has ongoing hemolysis; patient 2 has marrow failure`, r`Patient 1 has marrow failure; patient 2 has ongoing hemolysis`, r`Patient 1 has marrow failure; patient 2 has a recent hemorrhage`, r`Patient 1 has untreated iron deficiency; patient 2 has hemolysis`],
    correctAnswer: 0,
    explanation: r`Reticulocytes are newly released red cells, so a high count shows a healthy marrow compensating for cells being lost or destroyed. A low count in an anemic patient means the marrow itself is not producing. Marrow failure and untreated iron deficiency are production problems and cannot give a high count, while hemolysis and hemorrhage raise it.`,
  },
  [r`What happens in lymph node germinal centers during an infection?`]: {
    question: r`A child with a bacterial throat infection has swollen, tender lymph nodes in the neck. What mainly accounts for the enlargement of the nodes?`,
    options: [r`Naive T cells being produced from marrow stem cells`, r`Neutrophils maturing and dividing in the node cortex`, r`Red blood cells pooling in the germinal centers`, r`Activated B cells multiplying in the germinal centers`],
    correctAnswer: 3,
    explanation: r`Antigen-activated B cells proliferate in germinal centers, where they also undergo affinity maturation and class switching with T helper support, and this expansion swells the node. Nodes filter lymph, not blood, so red cells do not pool there. T cells mature in the thymus and neutrophils in the marrow.`,
  },
  [r`During exercise, early stroke-volume gains plateau, so further increases in cardiac output come mainly from {{c1::heart rate}}.`]: {
    question: r`At moderate exercise an athlete has a heart rate of 120 beats/min and a stroke volume of 100 mL, for a cardiac output of 12 L/min. At maximal effort her heart rate is 180 beats/min. What is her cardiac output most likely to be?`,
    options: [r`About 12 L/min, because cardiac output has already peaked`, r`About 27 L/min, because stroke volume also rises by half`, r`About 18 L/min, because stroke volume stays near 100 mL`, r`About 9 L/min, because stroke volume falls to half its value`],
    correctAnswer: 2,
    explanation: r`Stroke volume plateaus at moderate intensity, so beyond that point heart rate alone carries the rise: 180 × 0.100 L = 18 L/min. The 27 L/min answer wrongly lets stroke volume keep climbing with heart rate, 12 L/min assumes output stops rising, and 9 L/min assumes stroke volume collapses.`,
  },
  [r`Name the two dermal layers, and what does the dermis contain that the epidermis lacks?`]: {
    question: r`A skin section shows finger-like projections of loose connective tissue, each holding a capillary loop, pushing up into the underside of the epidermis. Which region is this?`,
    options: [r`Hypodermis, the fatty layer below the dermis`, r`Reticular dermis, the deep dense dermal layer`, r`Papillary dermis, the superficial dermal layer`, r`Stratum basale, the deepest epidermal layer`],
    correctAnswer: 2,
    explanation: r`Dermal papillae of loose, vascular tissue define the papillary dermis, the upper of the two dermal layers. The reticular dermis lies beneath it and is dense, not loose. Capillaries rule out any epidermal layer because the epidermis is avascular, and the hypodermis is fat far from the epidermis.`,
  },
  [r`How do sebaceous glands secrete, and what does sebum accomplish?`]: {
    question: r`In a gland that opens into a hair follicle, the secretory cells fill with lipid and then break apart completely, so the dead cells themselves become the secretion. Which description fits?`,
    options: [r`Holocrine secretion by an eccrine gland`, r`Holocrine secretion by a sebaceous gland`, r`Merocrine secretion by an eccrine gland`, r`Merocrine secretion by a sebaceous gland`],
    correctAnswer: 1,
    explanation: r`Secretion by rupture of the whole cell is holocrine, and the lipid product released into a hair follicle is sebum from a sebaceous gland. Merocrine secretion is exocytosis that leaves the cell intact, which is how eccrine sweat glands release their watery product onto the skin surface.`,
  },
  [r`What are the three core functions of the lymphatic system?`]: {
    question: r`Albumin tagged with a dye slowly leaks from leg capillaries into the interstitial space. By which route does this escaped protein normally get back into the blood?`,
    options: [r`Lymphatic vessels, through lymph nodes, into the venous blood`, r`Hepatic portal vein, through the liver, into the vena cava`, r`Arterial ends of capillaries, pushed by hydrostatic pressure`, r`Venous ends of capillaries, pulled in by oncotic pressure`],
    correctAnswer: 0,
    explanation: r`Returning filtered fluid and escaped plasma proteins to the blood is a core lymphatic job, and the lymph passes through nodes on the way to the veins. Proteins are too large to re-enter capillaries, and oncotic pressure moves water, not protein. The portal vein drains the gut, not the leg.`,
  },
  [r`Why can the liver make ketone bodies but not consume them?`]: {
    question: r`A drug blocks thiophorase (succinyl-CoA:acetoacetate transferase) in every tissue of a fasting animal. In which organ does fuel use stay the same as before the drug?`,
    options: [r`Liver, because it normally lacks this enzyme`, r`Brain, because ketones cannot cross into it`, r`Heart, because it normally burns only glucose`, r`Muscle, because it normally lacks mitochondria`],
    correctAnswer: 0,
    explanation: r`The liver makes ketone bodies but has no thiophorase, so it never oxidizes them and loses nothing when the enzyme is blocked. Heart and skeletal muscle have mitochondria and burn ketones readily, and ketones do cross the blood-brain barrier to fuel the brain during a fast.`,
  },
  [r`Exercising muscle steals blood flow because local metabolites ({{c1::adenosine, CO2, H+, K+}}) dilate its arterioles, overriding sympathetic tone.`]: {
    question: r`During hard cycling, sympathetic nerves release norepinephrine onto arterioles throughout the body, yet the arterioles in the working thigh muscles widen. What causes this widening?`,
    options: [r`Renin and angiotensin II released from the kidneys`, r`Low CO₂ and low H⁺ in the fluid around active fibers`, r`Acetylcholine released by vagal fibers in the muscle`, r`Adenosine, CO₂, H⁺ and K⁺ released by the active fibers`],
    correctAnswer: 3,
    explanation: r`Active muscle produces adenosine, CO₂, H⁺ and K⁺, and these local metabolites dilate its own arterioles strongly enough to override sympathetic constriction. Working muscle raises CO₂ and H⁺, it does not lower them. The vagus does not supply limb vessels, and angiotensin II constricts.`,
  },
  [r`Why do arterial PO2 and PCO2 stay nearly constant during moderate exercise?`]: {
    question: r`A jogger at a steady, moderate pace is producing CO₂ at three times her resting rate. Her arterial PCO₂ at rest was 40 mmHg. What is it most likely to be now?`,
    options: [r`About 40 mmHg, because ventilation has also roughly tripled`, r`About 80 mmHg, because ventilation lags behind metabolism`, r`About 120 mmHg, because CO₂ production has roughly tripled`, r`About 13 mmHg, because ventilation rises far more than CO₂`],
    correctAnswer: 0,
    explanation: r`In moderate exercise ventilation rises in proportion to CO₂ production, driven by feedforward signals from the motor cortex and muscle afferents, so arterial PCO₂ stays near 40 mmHg. A tripled or doubled PCO₂ ignores the rise in breathing, and a large fall would need hyperventilation beyond metabolic demand, which appears only near maximal effort.`,
  },
  [r`Sequence the energy systems powering the first minutes of intense exercise.`]: {
    question: r`Three athletes each give an all-out effort: a 10-second sprint, a 60-second run, and a 2-hour race. Which list gives the main ATP source for each, in that order?`,
    options: [r`Creatine phosphate, oxidative phosphorylation, anaerobic glycolysis`, r`Oxidative phosphorylation, anaerobic glycolysis, creatine phosphate`, r`Anaerobic glycolysis, creatine phosphate, oxidative phosphorylation`, r`Creatine phosphate, anaerobic glycolysis, oxidative phosphorylation`],
    correctAnswer: 3,
    explanation: r`Creatine phosphate regenerates ATP for about the first ten seconds, anaerobic glycolysis dominates for the next minute or so while lactate builds, and oxidative phosphorylation supplies sustained effort. The other lists put the fastest, smallest store later than a slower system or use the slow aerobic system for the sprint.`,
  },
  [r`Hepatic glycogen sustains blood glucose for roughly {{c1::12-24 hours}} of fasting; after that, gluconeogenesis dominates.`]: {
    question: r`A healthy adult has eaten nothing for 48 hours, and blood glucose is still in the normal range. What is the main source of that glucose?`,
    options: [r`Muscle glycogen breakdown, since muscle exports glucose in a long fast`, r`Liver glycogen breakdown, since liver glycogen lasts for about a week`, r`Liver gluconeogenesis, since liver glycogen ran out after about a day`, r`Liver gluconeogenesis, since liver glycogen is never used during a fast`],
    correctAnswer: 2,
    explanation: r`Liver glycogen holds blood glucose for roughly 12 to 24 hours, so by 48 hours gluconeogenesis from lactate, glycerol and amino acids is doing the work. Glycogen does not last a week, and it is used first, not never. Muscle lacks glucose-6-phosphatase and cannot release glucose into blood.`,
  },
  [r`Monocytes circulate briefly, then enter tissues and differentiate into {{c1::macrophages}} and related dendritic cells.`]: {
    question: r`A patient's marrow stops releasing monocytes but makes every other blood cell normally. Which population would fail to be replenished in a healing wound?`,
    options: [r`Neutrophils that arrive first and engulf bacteria`, r`Macrophages that engulf debris and present antigen`, r`Mast cells that release histamine into the wound`, r`Plasma cells that secrete antibody into the wound`],
    correctAnswer: 1,
    explanation: r`Monocytes leave the blood and differentiate into tissue macrophages (and related dendritic cells), which clear debris and present antigen on MHC class II. Plasma cells come from B lymphocytes, neutrophils are released from marrow already mature, and mast cells arise from their own precursors.`,
  },
  [r`Skin cools the body mainly by {{c1::evaporation of eccrine sweat}} plus dilation of dermal blood vessels.`]: {
    question: r`A runner trains at 38 °C in air that is saturated with water vapor. He is drenched in sweat but his core temperature keeps climbing. Why is sweating failing to cool him?`,
    options: [r`Sweat cannot evaporate, so it carries off almost no heat`, r`Apocrine glands take over, so the sweat is too oily`, r`Dermal vessels constrict, so no heat reaches the skin`, r`Sweat ducts close up, so no fluid reaches the skin surface`],
    correctAnswer: 0,
    explanation: r`Eccrine sweat cools only when it evaporates, because evaporation is what removes heat. In saturated air it drips off instead. He is visibly sweating, so the ducts are open. In heat the dermal vessels dilate, and apocrine glands serve scent, not temperature control.`,
  },
  [r`Erythropoietin is secreted by the {{c1::kidney}} in response to low oxygen delivery, stimulating red blood cell production.`]: {
    question: r`A patient with long-standing kidney failure has anemia with a low reticulocyte count, while iron, B12 and folate are all normal. Which treatment addresses the cause?`,
    options: [r`Thrombopoietin, a hormone the failing kidneys no longer secrete`, r`Intrinsic factor, a protein the failing kidneys no longer secrete`, r`Erythropoietin, a hormone the failing kidneys no longer secrete`, r`Erythropoietin, a hormone the bone marrow can no longer secrete`],
    correctAnswer: 2,
    explanation: r`Cells in the kidney sense low oxygen delivery and release erythropoietin, which drives red cell production in marrow, so failed kidneys leave the marrow unstimulated. The marrow responds to erythropoietin and does not make it. Thrombopoietin controls platelets, and intrinsic factor comes from gastric parietal cells.`,
  },
  [r`Why can a red blood cell not use the oxygen it carries?`]: {
    question: r`Cyanide blocks complex IV of the electron transport chain. In which cell is ATP production least affected by the poison?`,
    options: [r`A mature red blood cell, which has no mitochondria`, r`A cardiac muscle cell, which burns fatty acids`, r`A cortical neuron, which depends on glucose`, r`A liver cell, which holds a store of glycogen`],
    correctAnswer: 0,
    explanation: r`Mature red cells have ejected their mitochondria and make all their ATP by anaerobic glycolysis, so a block in the electron transport chain changes nothing for them. Heart, brain and liver cells all rely on oxidative phosphorylation, whatever fuel they start from.`,
  },
  [r`Dietary fats absorbed as chylomicrons enter {{c1::lacteals (lymphatic vessels)}} and reach blood via the thoracic duct, bypassing the liver.`]: {
    question: r`A very fat-soluble drug is packaged into chylomicrons inside intestinal cells. A water-soluble drug is absorbed into intestinal capillaries. How do their routes differ?`,
    options: [r`The fat-soluble drug enters the portal vein and reaches the liver first`, r`The fat-soluble drug enters lacteals and reaches the veins before the liver`, r`Both drugs enter the portal vein, so both reach the liver before the veins`, r`The water-soluble drug enters lacteals and reaches the veins before the liver`],
    correctAnswer: 1,
    explanation: r`Chylomicrons are too large for intestinal capillaries, so they enter lymphatic lacteals and drain through the thoracic duct into venous blood, bypassing first-pass processing in the liver. Water-soluble molecules take the capillaries and the hepatic portal vein. The wrong options swap the two routes or send both through the portal vein.`,
  },
  [r`Why does low plasma albumin (liver failure, malnutrition) cause edema?`]: {
    question: r`In a capillary, hydrostatic pressure is 30 mmHg and plasma oncotic pressure is 25 mmHg (interstitial pressures are zero). Liver failure lowers albumin until plasma oncotic pressure is 15 mmHg. What happens to the net pressure driving fluid out?`,
    options: [r`It rises from 30 to 45 mmHg outward, favoring edema`, r`It falls from 5 to −5 mmHg, favoring reabsorption`, r`It stays at 5 mmHg outward, so nothing changes`, r`It rises from 5 to 15 mmHg outward, favoring edema`],
    correctAnswer: 3,
    explanation: r`Net filtration pressure is hydrostatic minus oncotic: 30 − 25 = 5 mmHg before and 30 − 15 = 15 mmHg after. Albumin supplies the inward pull, so losing it leaves more fluid in the tissues. A fall treats oncotic pressure as an outward force, no change ignores oncotic pressure, and 45 mmHg adds the two pressures.`,
  },
  [r`In exercising muscle the O2-hemoglobin curve shifts {{c1::right}} — high CO2, H+, temperature, and 2,3-BPG all favor O2 unloading.`]: {
    question: r`P50 is the PO₂ at which hemoglobin is half saturated, about 27 mmHg in resting arterial blood. In blood sampled inside a hard-working muscle, what is P50 most likely to be?`,
    options: [r`About 35 mmHg, a right shift that lowers O₂ affinity`, r`About 35 mmHg, a left shift that raises O₂ affinity`, r`About 20 mmHg, a left shift that raises O₂ affinity`, r`About 20 mmHg, a right shift that lowers O₂ affinity`],
    correctAnswer: 0,
    explanation: r`High CO₂, H⁺ and temperature in working muscle shift the curve to the right, so hemoglobin needs a higher PO₂ to reach half saturation and gives up O₂ more easily. A higher P50 is a right shift with lower affinity. A P50 of 20 mmHg would be a left shift, which holds on to O₂.`,
  },
  [r`What does the Cori cycle accomplish during exercise, and what is its energetic cost?`]: {
    question: r`During a sprint, muscle glycolysis gains 2 ATP by turning one glucose into two lactate. The liver then spends 6 ATP to rebuild one glucose from that lactate. What is the body's net ATP result for one turn of this cycle?`,
    options: [r`A net gain of 8 ATP, kept by the muscle`, r`A net gain of 4 ATP, kept by the muscle`, r`A net cost of 8 ATP, paid by the liver`, r`A net cost of 4 ATP, paid by the liver`],
    correctAnswer: 3,
    explanation: r`The Cori cycle gains 2 ATP in muscle and spends 6 ATP in the liver, so the body as a whole is down 4 ATP per turn: 2 − 6 = −4. The cycle is worth it because it moves the energy burden to the liver while muscle keeps working anaerobically. The answers of 8 add the two numbers, and the gains reverse the sign.`,
  },
  [r`Fatty acids cannot become glucose because {{c1::acetyl-CoA cannot be converted back to pyruvate}}; pyruvate dehydrogenase is irreversible.`]: {
    question: r`During a fast, adipose tissue releases one triglyceride made of glycerol (3 carbons) and three 16-carbon fatty acids (48 carbons). How many of these 51 carbons can the liver turn into net new glucose?`,
    options: [r`Only the 48 carbons of the three fatty acids`, r`All 51 carbons of the whole triglyceride`, r`Only 24 carbons, half of each fatty acid`, r`Only the 3 carbons of the glycerol backbone`],
    correctAnswer: 3,
    explanation: r`Even-chain fatty acids are oxidized entirely to acetyl-CoA, and acetyl-CoA cannot be turned back into pyruvate because pyruvate dehydrogenase is irreversible. Its two carbons are lost as CO₂ in the TCA cycle. Only glycerol enters gluconeogenesis, so the answers counting fatty acid carbons are wrong.`,
  },
  [r`In prolonged starvation the brain derives much of its energy from {{c1::ketone bodies}}, sparing muscle protein.`]: {
    question: r`Urinary nitrogen measures how fast body protein is being broken down. Compared with day 3 of a total fast, what happens to urinary nitrogen by week 3, and why?`,
    options: [r`It falls, because the brain now burns ketones and needs less glucose`, r`It rises, because the brain now needs more glucose made from protein`, r`It falls, because the muscles have run out of protein to break down`, r`It rises, because ketone bodies are built from amino acid nitrogen`],
    correctAnswer: 0,
    explanation: r`Once the brain takes much of its energy from ketone bodies, far less glucose has to be made from amino acids, so muscle protein breakdown and nitrogen loss drop. That sparing of protein is the point of the adaptation. Muscle protein has not run out, and ketones are made from acetyl-CoA and contain no nitrogen.`,
  },
  [r`The fasted hormone signature: insulin {{c1::low}}, glucagon high — unleashing hormone-sensitive lipase in adipose tissue.`]: {
    question: r`A fasting volunteer is given insulin by vein, with enough glucose to keep blood sugar steady. What happens to the level of free fatty acids in the plasma?`,
    options: [r`It falls, because insulin activates hormone-sensitive lipase`, r`It falls, because insulin inhibits hormone-sensitive lipase`, r`It rises, because insulin inhibits fatty acid synthesis`, r`It rises, because insulin activates hormone-sensitive lipase`],
    correctAnswer: 1,
    explanation: r`In the fasted state low insulin releases the brake on hormone-sensitive lipase in adipose tissue, so fatty acids pour out. Giving insulin restores the brake and plasma fatty acids fall. Insulin does not activate this lipase, and it stimulates fatty acid synthesis.`,
  },
  [r`UV light in skin converts {{c1::7-dehydrocholesterol}} into vitamin D3 (cholecalciferol), the first step of vitamin D synthesis.`]: {
    question: r`A person spends a sunless polar winter with no vitamin D in the diet and develops soft bones. The liver and kidneys are healthy. Which step of vitamin D synthesis is missing?`,
    options: [r`UV conversion of 7-dehydrocholesterol to cholecalciferol in skin`, r`Addition of the 1α-hydroxyl group to form calcitriol in kidney`, r`Addition of the 25-hydroxyl group to cholecalciferol in liver`, r`UV conversion of cholecalciferol to active calcitriol in skin`],
    correctAnswer: 0,
    explanation: r`Without ultraviolet light the skin cannot convert 7-dehydrocholesterol to vitamin D3 (cholecalciferol), the first step. The liver and kidney hydroxylations are intact here but have nothing to work on. Skin does not make calcitriol directly: that takes the liver and then the kidney.`,
  },
  [r`Why do people of very different skin tones have similar numbers of melanocytes?`]: {
    question: r`Skin biopsies are taken from the same site on a very dark-skinned person and a very light-skinned person. What difference is expected?`,
    options: [r`Many more melanocytes in light skin, with less melanin per cell`, r`Similar melanin amounts, with more keratinocytes in dark skin`, r`Similar melanocyte numbers, with more melanin made in dark skin`, r`Many more melanocytes in dark skin, with equal melanin per cell`],
    correctAnswer: 2,
    explanation: r`Skin tone depends on how much melanin, and which type, the melanocytes make and pass to keratinocytes, not on how many melanocytes there are. The counts are similar in both samples. The wrong options make cell number the variable or claim the melanin content is the same.`,
  },
  [r`Platelets are anucleate cytoplasmic fragments budded from marrow {{c1::megakaryocytes}}.`]: {
    question: r`A toxin selectively destroys megakaryocytes in the bone marrow and leaves every other marrow cell untouched. What is the patient most likely to show two weeks later?`,
    options: [r`A low red cell count with marked fatigue`, r`A low lymphocyte count with viral illness`, r`A low platelet count with prolonged bleeding`, r`A low neutrophil count with repeated infection`],
    correctAnswer: 2,
    explanation: r`Platelets are fragments shed by megakaryocytes and last only about 8 to 10 days, so two weeks without megakaryocytes empties the blood of platelets and bleeding follows. Neutrophils, red cells and lymphocytes come from other precursors, which the toxin spared.`,
  },
  [r`Rank the leukocytes by abundance, and name the first responder to bacterial infection.`]: {
    question: r`A normal white cell differential lists five cell types at about 60, 30, 6, 3 and 1 percent. The most abundant type is also the first to arrive at a bacterial infection. Which cells are the most abundant and the rarest?`,
    options: [r`Neutrophils are most abundant; eosinophils are rarest`, r`Lymphocytes are most abundant; basophils are rarest`, r`Monocytes are most abundant; lymphocytes are rarest`, r`Neutrophils are most abundant; basophils are rarest`],
    correctAnswer: 3,
    explanation: r`The order of abundance is neutrophils, lymphocytes, monocytes, eosinophils, basophils, and neutrophils are the first responders that engulf bacteria. Lymphocytes are second, not first. Eosinophils sit fourth at about 3 percent, and monocytes are third.`,
  },
  [r`All blood cells descend from one {{c1::hematopoietic stem cell}} in bone marrow, which splits into myeloid and lymphoid lineages.`]: {
    question: r`A mutation blocks the common lymphoid progenitor in bone marrow while the myeloid progenitor works normally. Which cells will be missing from the blood?`,
    options: [r`B cells, T cells and neutrophils`, r`T cells, monocytes and platelets`, r`B cells, T cells and natural killer cells`, r`B cells, eosinophils and red cells`],
    correctAnswer: 2,
    explanation: r`The hematopoietic stem cell splits into a lymphoid line (B, T and natural killer cells) and a myeloid line (red cells, platelets, granulocytes and monocytes). Natural killer cells are lymphoid even though they act in innate immunity. Neutrophils, eosinophils, monocytes, platelets and red cells are all myeloid and would be spared.`,
  },
  [r`Name the three main gluconeogenic substrates during fasting and their tissue sources.`]: {
    question: r`A drug completely blocks the breakdown of triglyceride in adipose tissue of a fasting patient. The supply of which gluconeogenic substrate to the liver falls directly?`,
    options: [r`Alanine, normally released from adipose triglyceride`, r`Glycerol, normally released from adipose triglyceride`, r`Acetyl-CoA, normally made into glucose by the liver`, r`Lactate, normally released from adipose triglyceride`],
    correctAnswer: 1,
    explanation: r`The three fasting substrates are lactate from red cells and muscle, alanine from muscle protein, and glycerol from adipose lipolysis, so blocking lipolysis removes glycerol. Lactate and alanine do not come from triglyceride. Acetyl-CoA is not a gluconeogenic substrate at all.`,
  },
  [r`Which tissues remain obligate glucose users even in deep starvation, and why?`]: {
    question: r`After four weeks of starvation most tissues run on fatty acids or ketone bodies. Which cell type still depends entirely on glucose, and why?`,
    options: [r`Hepatocytes, because the liver cannot carry out β-oxidation`, r`Cortical neurons, because ketones cannot enter the brain`, r`Red blood cells, because they have no mitochondria at all`, r`Cardiac myocytes, because the heart cannot burn fatty acids`],
    correctAnswer: 2,
    explanation: r`Fatty acids and ketone bodies can only be oxidized in mitochondria, and red cells have none, so glycolysis is their only source of ATP. The brain does take up ketones and gets most of its energy from them in starvation, although it keeps a small glucose need. Heart and liver both oxidize fatty acids.`,
  },
  [r`What defines connective tissue histologically, and which cell secretes its protein fibers?`]: {
    question: r`A tissue section shows a few scattered spindle-shaped cells surrounded by a large volume of protein fibers and ground substance. What is the tissue, and what are the cells doing?`,
    options: [r`Muscle tissue; smooth myocytes secreting elastin`, r`Connective tissue; fibroblasts secreting collagen`, r`Connective tissue; macrophages secreting collagen`, r`Epithelial tissue; keratinocytes secreting keratin`],
    correctAnswer: 1,
    explanation: r`Tissue that is mostly extracellular matrix with few cells is connective tissue, and its fibers (collagen and elastin) are secreted by fibroblasts. Macrophages are phagocytes and do not build the matrix. Epithelium and muscle are packed with cells and have little matrix.`,
  },
  [r`Epithelium is avascular: it is nourished by diffusion from underlying connective tissue across the {{c1::basement membrane}}.`]: {
    question: r`A cervical biopsy shows cancerous epithelial cells through the full thickness of the epithelium, but the basement membrane is intact. Why can this tumor not yet have spread through the blood?`,
    options: [r`Tumor cells at this early stage have not yet begun to divide`, r`Blood carries epithelial cells only as far as the nearest lymph node`, r`No blood vessels lie on the epithelial side of the basement membrane`, r`Blood vessels inside the epithelium have walls too thick to enter`],
    correctAnswer: 2,
    explanation: r`Epithelium is avascular: it is fed by diffusion from vessels in the connective tissue beneath the basement membrane. Cells that have not crossed that membrane have no vessel to enter. There are no vessels within the epithelium, and a tumor filling the full thickness is clearly dividing.`,
  },
  [r`Why is simple squamous epithelium found in alveoli and capillaries, while stratified squamous lines skin and esophagus?`]: {
    question: r`In an engineered mouse the alveoli are lined by stratified squamous epithelium in place of the normal simple squamous lining. What is the main consequence?`,
    options: [r`Gas exchange slows, because the surface cells carry cilia`, r`Gas exchange speeds up, because the surface area is larger`, r`Gas exchange slows, because the diffusion distance is longer`, r`Gas exchange is unchanged, because the cells are still flat`],
    correctAnswer: 2,
    explanation: r`A single layer of flat cells keeps the path for diffusion as short as possible. Stacking many layers protects against abrasion, as in skin and the esophagus, but lengthens that path and slows exchange. Layering does not add surface area or cilia, and the number of layers, not cell shape, sets the distance.`,
  },
  [r`The trachea and bronchi are lined by {{c1::pseudostratified ciliated columnar}} epithelium with goblet cells (the mucociliary escalator).`]: {
    question: r`In a biopsy of the trachea, every cell touches the basement membrane, but the nuclei sit at different heights so the lining looks layered. The tall cells bear cilia, and mucus-secreting cells are scattered among them. Which epithelium is this?`,
    options: [r`Stratified squamous epithelium with goblet cells`, r`Stratified ciliated columnar epithelium`, r`Simple ciliated cuboidal epithelium`, r`Pseudostratified ciliated columnar epithelium`],
    correctAnswer: 3,
    explanation: r`A lining that only looks layered, because every cell actually reaches the basement membrane, is pseudostratified. With cilia and goblet cells it forms the mucociliary escalator of the trachea and bronchi. In truly stratified epithelium only the bottom layer touches the membrane, and the cells described are tall, not cuboidal or flat.`,
  },
  [r`The two excitable tissue types, capable of firing action potentials, are {{c1::muscle and nervous tissue}}.`]: {
    question: r`A toxin disables every voltage-gated ion channel in the body. The primary function of which tissue types is abolished directly?`,
    options: [r`Nervous tissue and muscle tissue`, r`Muscle tissue and connective tissue`, r`Epithelial tissue and connective tissue`, r`Nervous tissue and epithelial tissue`],
    correctAnswer: 0,
    explanation: r`Only nervous and muscle tissue are excitable, meaning they fire and propagate action potentials with voltage-gated channels. Epithelium works by forming barriers and transporting substances, and connective tissue gives structural and metabolic support, so neither depends on action potentials.`,
  },
  [r`Epidermal mitosis occurs only in the {{c1::stratum basale}}; cells die as they migrate outward toward the stratum corneum.`]: {
    question: r`A chemotherapy drug kills only cells that are in mitosis. In which layer of the epidermis will it kill cells directly?`,
    options: [r`Stratum corneum, the surface layer`, r`Stratum lucidum, a clear thin layer`, r`Stratum basale, the deepest layer`, r`Stratum granulosum, a middle layer`],
    correctAnswer: 2,
    explanation: r`Keratinocytes divide only in the stratum basale, next to the basement membrane. As cells move outward they fill with keratin, stop dividing and lose their nuclei, so the layers above contain no mitotic cells and the corneum is made of dead cells.`,
  },
  [r`Hemolysis raises reticulocytes, lactate dehydrogenase, and indirect bilirubin while {{c1::haptoglobin}} falls.`]: {
    question: r`Red cells are bursting inside a patient's blood vessels and spilling hemoglobin into the plasma. Which plasma protein falls to a very low level, and why?`,
    options: [r`Transferrin, because it is used up binding free hemoglobin`, r`Haptoglobin, because it is used up binding free hemoglobin`, r`Albumin, because it is used up binding the excess bilirubin`, r`Ferritin, because it is used up binding the released iron`],
    correctAnswer: 1,
    explanation: r`Haptoglobin binds free hemoglobin and the complex is cleared, so in hemolysis haptoglobin is consumed and its level drops. Transferrin carries iron, not hemoglobin. Albumin carries unconjugated bilirubin without being depleted, and ferritin stores iron inside cells and tends to rise.`,
  },
  [r`Trace why autoimmune destruction of gastric parietal cells causes anemia only years later.`]: {
    question: r`A patient's stomach is removed entirely and no vitamin supplements are given. When is megaloblastic anemia expected to appear, and why?`,
    options: [r`Never, because the ileum absorbs B12 without any gastric help`, r`After several years, once the liver's B12 store is used up`, r`Within a few weeks, once the blood's B12 supply is used up`, r`After several years, once the liver's iron store is used up`],
    correctAnswer: 1,
    explanation: r`Without parietal cells there is no intrinsic factor, and the terminal ileum cannot take up B12 without it. The liver holds a B12 store that lasts several years, so the anemia is delayed. Iron deficiency gives small red cells, not megaloblasts, and B12 uptake in the ileum does depend on the stomach.`,
  },
  [r`Predict where infused isotonic saline, 5 percent dextrose in water, and hypertonic saline each distribute.`]: {
    question: r`One liter of 5 percent dextrose in water is infused and the glucose is fully metabolized. Body water is two-thirds intracellular and one-third extracellular. Where does the liter of water end up?`,
    options: [r`About 250 mL in extracellular fluid and 750 mL inside cells`, r`About 1,000 mL in extracellular fluid and none inside cells`, r`About 670 mL in extracellular fluid and 330 mL inside cells`, r`About 330 mL in extracellular fluid and 670 mL inside cells`],
    correctAnswer: 3,
    explanation: r`Once the glucose is used, what remains is free water, which spreads across all compartments in proportion to their size: one-third (about 330 mL) extracellular and two-thirds (about 670 mL) intracellular. Keeping all of it extracellular describes isotonic saline. The other answers swap the fractions or use one-quarter, which is the plasma share of extracellular fluid.`,
  },
  [r`Why does hemolytic disease of the newborn usually spare the first Rh-positive pregnancy?`]: {
    question: r`An Rh-negative woman received a transfusion of Rh-positive blood years ago. She is now in her first pregnancy, and the fetus is Rh-positive. Is this fetus at risk of hemolytic disease?`,
    options: [r`Yes, because she already makes anti-D IgG that crosses the placenta`, r`Yes, because every Rh-negative woman is born making anti-D IgM`, r`No, because her anti-D is IgM, which cannot cross the placenta`, r`No, because a first pregnancy is never affected by anti-D antibody`],
    correctAnswer: 0,
    explanation: r`A first Rh-positive pregnancy is usually spared only because the mother is first sensitized at delivery. This woman was sensitized by the transfusion, so she already makes anti-D IgG, which crosses the placenta. Anti-D is not preformed and is IgG, unlike the IgM antibodies of the ABO system.`,
  },
  [r`Predict the fluid, temperature, and infection consequences of losing a large area of skin to a burn.`]: {
    question: r`A patient loses the skin over 40 percent of the body in a fire. Which problem threatens life in the first day, and by what mechanism?`,
    options: [r`Fluid overload, from loss of the sweat glands that excrete water`, r`Hypertension, from plasma trapped beneath the burned skin surface`, r`Hypovolemic shock, from evaporative water loss and leaky capillaries`, r`Hyperthermia, from loss of the fat that insulates the body core`],
    correctAnswer: 2,
    explanation: r`Skin is the barrier to evaporation, so without it water loss soars, and capillary leak moves still more plasma out of the vessels: the result is low blood volume and shock. The patient loses fluid, not gains it, and blood pressure falls. Losing skin lets heat escape, so the risk is cooling, with infection as the main later danger.`,
  },
  [r`Explain the four cardinal signs of acute inflammation mechanistically.`]: {
    question: r`Minutes after a bee sting, the skin around it is red, warm, swollen and painful. Which mechanism accounts specifically for the swelling?`,
    options: [r`Dilated arterioles carrying a greater blood flow`, r`Bradykinin acting directly on the nociceptors`, r`Constricted arterioles trapping blood in the area`, r`More permeable venules leaking protein-rich fluid`],
    correctAnswer: 3,
    explanation: r`Histamine and prostaglandins make venules leaky, so protein-rich exudate enters the tissue and causes swelling. Arteriolar dilation raises blood flow, which explains the redness and heat. Bradykinin sensitizes pain fibers, which explains the pain, and arterioles dilate in inflammation rather than constrict.`,
  },
  [r`Why can a marathon runner who drinks only plain water become hyponatremic?`]: {
    question: r`A marathon runner loses 4 L of sweat containing 50 mmol/L of Na⁺ and drinks 4 L of plain water during the race. What happens to her plasma Na⁺ concentration?`,
    options: [r`It rises: sweat is hypotonic, so more water than Na⁺ has been lost`, r`It is unchanged: 4 L of fluid went out and 4 L of fluid came in`, r`It falls: 200 mmol of Na⁺ is gone but the water was fully replaced`, r`It falls: sweat is hypertonic, so mostly Na⁺ and little water is lost`],
    correctAnswer: 2,
    explanation: r`Sweat is hypotonic but still carries sodium: 4 L × 50 mmol/L = 200 mmol lost. Replacing the volume with water that has no sodium dilutes what is left, and ADH released in exercise stops the kidney from clearing the extra water. Plasma sodium would rise only if she drank nothing, and matching volumes does not match solute.`,
  },
  [r`Iron deficiency versus anemia of chronic disease: contrast ferritin, transferrin, and total iron-binding capacity.`]: {
    question: r`Two patients have anemia with low serum iron. Patient 1 has had heavy menstrual bleeding for a year. Patient 2 has had active rheumatoid arthritis for a year. What do ferritin and total iron-binding capacity (TIBC) show?`,
    options: [r`Patient 1: low ferritin, low TIBC. Patient 2: high ferritin, high TIBC`, r`Patient 1: high ferritin, low TIBC. Patient 2: low ferritin, high TIBC`, r`Patient 1: low ferritin, high TIBC. Patient 2: low ferritin, high TIBC`, r`Patient 1: low ferritin, high TIBC. Patient 2: high ferritin, low TIBC`],
    correctAnswer: 3,
    explanation: r`Chronic blood loss empties iron stores, so ferritin is low and the liver makes more transferrin, raising TIBC. Chronic inflammation raises hepcidin, which traps iron in macrophages: stores (ferritin) are normal or high while TIBC is low. The other answers swap the two patterns, mix them, or treat both patients as iron deficient.`,
  },
  [r`B12 and folate deficiency both cause megaloblastic anemia, but only B12 deficiency causes {{c1::neurologic}} damage.`]: {
    question: r`Two patients have megaloblastic anemia with high homocysteine. Only patient 2 also has numb feet, loss of vibration sense, and a high methylmalonic acid level. What is patient 2 lacking?`,
    options: [r`Vitamin B12, which methylmalonyl-CoA mutase requires`, r`Iron, which is needed to make large red cells`, r`Folate, which methylmalonyl-CoA mutase requires`, r`Folate, which alone is required to maintain myelin`],
    correctAnswer: 0,
    explanation: r`Both B12 and folate deficiency give megaloblastic anemia and high homocysteine, but only B12 is the cofactor for methylmalonyl-CoA mutase. Without it methylmalonic acid builds up and myelin degenerates, giving neurologic damage. Folate deficiency spares the nerves, and iron deficiency gives small red cells.`,
  },
  [r`An anemia workup starts with mean corpuscular volume: microcytic means a {{c1::hemoglobin synthesis}} problem, macrocytic a DNA synthesis problem.`]: {
    question: r`An anemic patient has a mean corpuscular volume of 68 fL (normal 80 to 100 fL). Which pair of causes, and which underlying defect, fits this result?`,
    options: [r`B12 or folate deficiency: a DNA synthesis problem`, r`Iron deficiency or thalassemia: a DNA synthesis problem`, r`Iron deficiency or thalassemia: a hemoglobin synthesis problem`, r`B12 or folate deficiency: a hemoglobin synthesis problem`],
    correctAnswer: 2,
    explanation: r`An MCV below normal is microcytic, which points to impaired hemoglobin synthesis, as in iron deficiency and thalassemia: precursors keep dividing while they wait to fill with hemoglobin. B12 and folate deficiency slow DNA synthesis and give large cells, so they fit a high MCV, not 68 fL.`,
  },
  [r`A healing wound first lays down type {{c1::III}} collagen, later remodeled into stronger type I, reaching only about 80 percent of original strength.`]: {
    question: r`The scar from a surgical incision is sampled at one week and again at one year. What is expected of its collagen and its strength?`,
    options: [r`Mostly type III at one week, then type I at about 80 percent strength`, r`Mostly type III at one week, then type I at fully restored strength`, r`Mostly type I at one week, then type III at about 80 percent strength`, r`Mostly type I at one week, then type III at fully restored strength`],
    correctAnswer: 0,
    explanation: r`Granulation tissue first lays down type III collagen, which is remodeled over months into stronger type I. The original weave is never rebuilt, so the scar reaches only about 80 percent of the original tensile strength. The wrong answers reverse the two collagen types or claim full recovery.`,
  },
  [r`At rest tissues extract about {{c1::25}} percent of arterial oxygen; maximal exercise pushes extraction toward 75 percent.`]: {
    question: r`Arterial blood carries 20 mL of O₂ per dL. Using typical extraction fractions, what is the O₂ content of mixed venous blood at rest and at maximal exercise?`,
    options: [r`10 mL/dL at rest and 0 mL/dL at maximal exercise`, r`15 mL/dL at rest and 15 mL/dL at maximal exercise`, r`5 mL/dL at rest and 15 mL/dL at maximal exercise`, r`15 mL/dL at rest and 5 mL/dL at maximal exercise`],
    correctAnswer: 3,
    explanation: r`Tissues take about 25 percent of arterial oxygen at rest, which is 5 of 20 mL/dL and leaves 15. At maximal exercise extraction approaches 75 percent, which is 15 of 20 and leaves 5. The reversed answer confuses what is extracted with what remains, and extraction is neither 50 percent at rest nor constant.`,
  },
  [r`Heat exhaustion versus heat stroke: which one is still sweating, and what defines the emergency?`]: {
    question: r`A hiker is found confused on a hot trail with a core temperature of 41 °C and skin that is hot and dry. Which diagnosis fits, and what defines it?`,
    options: [r`Heat exhaustion: sweating has depleted volume but control is intact`, r`Heat exhaustion: dry skin shows that the body is conserving water`, r`Heat stroke: profuse sweating and low pressure are its key signs`, r`Heat stroke: temperature control has failed and the brain is affected`],
    correctAnswer: 3,
    explanation: r`Heat stroke is failure of central temperature control: core temperature above about 40 °C, hot dry skin and altered mental status make it an emergency. In heat exhaustion the patient is still sweating, weak and low in volume but thinking clearly. Profuse sweating describes exhaustion, not stroke.`,
  },
  [r`After marrow-suppressing chemotherapy, which blood cell line falls first, and what does that reveal about circulating lifespans?`]: {
    question: r`Chemotherapy completely stops a patient's bone marrow from making blood cells for 10 days. What will a blood count on day 10 most likely show?`,
    options: [r`Very few neutrophils, with a nearly normal red cell count`, r`Normal numbers of both, since both survive for months`, r`Neutrophils and red cells both reduced to the same degree`, r`Very few red cells, with a nearly normal neutrophil count`],
    correctAnswer: 0,
    explanation: r`Each line falls at a rate set by its lifespan in blood. Neutrophils last only hours, so they are nearly gone within a week to ten days. Red cells last about 120 days, so 10 days without production removes only a small fraction of them, and anemia appears last.`,
  },
  [r`Normal hemoglobin is about {{c1::15}} g/dL in men and 13.5 g/dL in women, with hematocrit roughly three times the hemoglobin value.`]: {
    question: r`A woman's hematocrit is 27 percent. Using the usual rule that links hematocrit to hemoglobin, what is her approximate hemoglobin, and how should it be read?`,
    options: [r`About 13.5 g/dL, which is normal for a woman`, r`About 9 g/dL, which is well below the normal 13.5 g/dL`, r`About 18 g/dL, which is above the normal 13.5 g/dL`, r`About 9 g/dL, which is close to normal for a woman`],
    correctAnswer: 1,
    explanation: r`Hematocrit is roughly three times hemoglobin, so 27 ÷ 3 = 9 g/dL. Normal is about 13.5 g/dL in women and 15 g/dL in men, so 9 is clearly anemic. The 13.5 answer divides by two, and 18 divides by 1.5.`,
  },
  [r`ABO antibodies are preformed {{c1::IgM}}, but anti-Rh antibodies are IgG produced only after sensitization.`]: {
    question: r`A patient with type O blood who has never been transfused or pregnant is mistakenly given type A red cells. What happens, and why?`,
    options: [r`Immediate hemolysis: donor anti-O attacks the patient`, r`No hemolysis: type O plasma holds no ABO antibodies`, r`Immediate hemolysis: anti-A IgM exists before any exposure`, r`No hemolysis: anti-A appears only after a first exposure`],
    correctAnswer: 2,
    explanation: r`ABO antibodies are preformed IgM, present without any earlier transfusion, so a first mismatch causes immediate intravascular hemolysis. Needing a prior exposure describes anti-Rh IgG, not the ABO system. Type O plasma carries both anti-A and anti-B, and there is no anti-O antibody.`,
  },
  [r`Why does vitamin C deficiency cause bleeding gums and wounds that reopen?`]: {
    question: r`A sailor who has eaten no fresh fruit for months has bleeding gums and old scars that reopen. What is wrong with the collagen his fibroblasts are making?`,
    options: [r`It has excess hydroxyproline, so the fibers are stiff and brittle`, r`It lacks γ-carboxyglutamate, so the fibers cannot bind calcium`, r`It lacks glycine, so the three chains cannot pack into a helix`, r`It lacks hydroxyproline, so its triple helices are less stable`],
    correctAnswer: 3,
    explanation: r`Vitamin C is the cofactor for prolyl and lysyl hydroxylase. Without hydroxylation, procollagen cannot form stable, cross-linked triple helices, so vessels and scars are fragile. Glycine is supplied normally, hydroxyproline is low rather than high, and γ-carboxylation is the vitamin K step for clotting factors.`,
  },
  [r`Body water is about {{c1::60}} percent of body mass: two-thirds intracellular, one-third extracellular, and one-quarter of the extracellular fluid is plasma.`]: {
    question: r`A 60 kg adult has typical body fluid proportions. About how much of this person's body water is blood plasma?`,
    options: [r`About 9 L, one-quarter of the 36 L of total body water`, r`About 3 L, one-quarter of the 12 L of extracellular fluid`, r`About 12 L, the whole extracellular fluid volume`, r`About 4 L, one-third of the 12 L of extracellular fluid`],
    correctAnswer: 1,
    explanation: r`Total body water is 60 percent of 60 kg, or 36 L. One-third of that, 12 L, is extracellular, and one-quarter of the extracellular fluid, 3 L, is plasma. The 12 L answer stops at extracellular fluid, 9 L takes a quarter of total water, and 4 L uses one-third where one-quarter belongs.`,
  },
}
